+    for (size_t i = 0; i < ret->count; i++) {
+        const AVExifEntry *entry = &ifd->entries[i];
+        AVExifEntry *ret_entry = &ret->entries[i];
+        int status = exif_clone_entry(ret_entry, entry);
+        if (status < 0)
+            goto fail;
+    }
