+            total_size += BASE_TAG_SIZE + exif_get_ifd_size(&entry->value.ifd) + entry->ifd_offset;
+        } else {
+            size_t payload_size = entry->count * exif_sizes[entry->type];
+            total_size += BASE_TAG_SIZE + (payload_size > 4 ? payload_size : 0);
+        }
+    }
+    return total_size;
